'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Multiplies each element in an input one-dimensional double-precision complex floating-point ndarray by a scalar constant and assigns the results to elements in a one-dimensional double-precision complex floating-point output ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant to multiply.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* var Complex128Vector = require( '@stdlib/ndarray/vector/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = new Complex128Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
* var w = new Complex128Vector( 2 );
*
* var alpha = scalar2ndarray( new Complex128( 5.0, 0.0 ), {
*     'dtype': 'complex128'
* });
*
* var out = zwax( [ x, w, alpha ] );
* // returns <ndarray>[ <Complex128>[ -10.0, 5.0 ], <Complex128>[ 15.0, -25.0 ] ]
*
* var bool = ( out === w );
* // returns true
*/
function zwax( arrays ) {
	var alpha = arrays[ 2 ];
	var x = arrays[ 0 ];
	var w = arrays[ 1 ];
	addon( reinterpret( getData( x ), 0 ), serialize( x ), reinterpret( getData( w ), 0 ), serialize( w ), reinterpret( getData( alpha ), 0 ), serialize( alpha ) ); // eslint-disable-line max-len
	return w;
}


// EXPORTS //

module.exports = zwax;
